      "keystrokes": "cat > main.cpp <<'CPP'\n#include <bits/stdc++.h>\nusing namespace std;\n\n// MagicCounter: counts numbers in base 'b' with even count of each digit in their base-b rep (no leading zeros).\nclass MagicCounter {\npublic:\n    int b;                 // base\n    int maxLen;              // maximum number of digits needed for N up to 1e18 in base b\n    int masks;               // 1 << b\n    vector<vector<unsigned long long>> A; // A[len][mask]: number of length-len tails with parity = mask (starting from zero parity)\n    vector<vector<unsigned long long>> H; // H[s][mask] = sum_{w=1}^{b-1} A[s][mask ^ (1<<w)]\n    vector<vector<unsigned long long>> G; // G[rem][mask] = sum_{s=0}^{rem-1} H[s][mask]\n\n    MagicCounter(int base) {\n        b = base;\n        const unsigned long long LIMIT = 1000000000000000000ULL; // 1e18\n        // compute maxLen such that b^maxLen > LIMIT, i.e., digits of LIMIT in base b\n        maxLen = 0;\n        unsigned long long t = LIMIT;\n        while (t > 0) { maxLen++; t /= b; }\n        if (maxLen == 0) maxLen = 1;\n        masks = 1 << b;\n\n        // Build A\n        A.assign(maxLen + 1, vector<unsigned long long>(masks, 0ULL));\n        A[0][0] = 1ULL;\n        for (int len = 1; len <= maxLen; ++len) {\n            for (int mask = 0; mask < masks; ++mask) {\n                unsigned long long sum = 0ULL;\n                for (int d = 0; d < b; ++d) {\n                    sum += A[len - 1][mask ^ (1 << d)];\n                }\n                A[len][mask] = sum;\n            }\n        }\n\n        // Build H\n        H.assign(maxLen, vector<unsigned long long>(masks, 0ULL));\n        for (int s = 0; s < maxLen; ++s) {\n            for (int m = 0; m < masks; ++m) {\n                unsigned long long sum = 0ULL;\n                for (int w = 1; w < b; ++w) {\n                    sum += A[s][m ^ (1 << w)];\n                }\n                H[s][m] = sum;\n            }\n        }\n\n        // Build G via prefix sums of H over s\n        G.assign(maxLen + 1, vector<unsigned long long>(masks, 0ULL));\n        for (int rem = 1; rem <= maxLen; ++rem) {\n            for (int m = 0; m < masks; ++m) {\n                G[rem][m] = G[rem - 1][m] + H[rem - 1][m];\n            }\n        }\n    }\n\n    // Count magic numbers in [1..N] for this base\n    unsigned long long countUpTo(unsigned long long N) {\n        if (N == 0ULL) return 0ULL; // nothing up to 0\n\n        // Build digits of N in base b (MSB to LSB)\n        vector<int> digits;\n        unsigned long long t = N;\n        while (t > 0) { digits.push_back((int)(t % b)); t /= b; }\n        reverse(digits.begin(), digits.end());\n        int L = (int)digits.size();\n\n        unsigned long long ans = 0ULL;\n        int started = 0; // 0 = not started (no nonzero yet), 1 = started\n        int mask = 0;    // parity mask accumulated so far\n\n        for (int i = 0; i < L; ++i) {\n            int limit = digits[i];\n            int rem = L - i - 1; // remaining positions after this\n            if (limit > 0) {\n                // Try placing x in [0, limit-1] here, which makes the rest free (tight becomes 0)\n                for (int x = 0; x < limit; ++x) {\n                    if (started == 0) {\n                        if (x == 0) {\n                            // still not started; number may start later within the remaining rem digits\n                            ans += G[rem][mask];\n                        } else {\n                            // first nonzero occurs here; tail length rem contributes A[rem][mask XOR (1<<x)]\n                            ans += A[rem][mask ^ (1 << x)];\n                        }\n                    } else {\n                        // already started; tail length rem contributes A[rem][mask XOR (1<<x)]\n                        ans += A[rem][mask ^ (1 << x)];\n                    }\n                }\n            }\n\n            // Now take the actual digit 'limit' and continue with tightness\n            if (started == 0) {\n                if (limit == 0) {\n                    // still not started\n                } else {\n                    started = 1;\n                    mask ^= (1 << limit);\n                }\n            } else {\n                mask ^= (1 << limit);\n            }\n        }\n        // After processing all digits, include N itself if it's magic\n        if (started == 1 && mask == 0) {\n            ans += 1ULL;\n        }\n        return ans;\n    }\n};\n\nint main(){\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n\n    int Q; if(!(cin >> Q)) return 0;\n    vector<unique_ptr<MagicCounter>> caches(11);\n    auto get = [&](int b) -> MagicCounter* {\n        if (!caches[b]) caches[b] = make_unique<MagicCounter>(b);\n        return caches[b].get();\n    };\n\n    while (Q--) {\n        int b; unsigned long long l, r; cin >> b >> l >> r;\n        MagicCounter* mc = get(b);\n        unsigned long long res = mc->countUpTo(r) - mc->countUpTo(l - 1);\n        cout << res << \"\\n\";\n    }\n    return 0;\n}\nCPP\n"
