/ fallback: whole graph is a tree (but problem guarantees n edges, so cycle exists)\n        start = 1;\n    }\n    cyc.push_back(start);\n    int prev = -1; int cur = start;\n    while(true){\n        int nxt = -1;\n        for(auto [to,eid] : adj[cur]){\n            if(!inCycle[to]) continue; // only cycle neighbors\n            if(to == prev) continue;\n            nxt = to; break;\n        }\n        if(nxt == -1) break;\n        if(nxt == start) { break; }\n        cyc.push_back(nxt);\n        prev = cur; cur = nxt;\n    }\n    int K = (int)cyc.size();\n    vector<int> pos(n+1, -1);\n    for(int i=0;i<K;++i) pos[cyc[i]] = i;\n\n    // 3) build tree info for vertices attached to cycle vertices\n    vector<int> root(n+1, -1); // which cycle vertex is the root of this vertex's tree\n    vector<int> depth(n+1, 0);\n    vector<int> parent(n+1, -1);\n    vector<int> edge_to_parent(n+1, -1);\n\n    // mark cycle vertices as their own root\n    for(int v : cyc){ root[v] = v; depth[v] = 0; parent[v] = -1; edge_to_parent[v] = -1; }\n\n    // DFS/BFS from each cycle vertex into its attached tree\n    for(int c : cyc){\n        for(auto [to, eid] : adj[c]){\n            if(inCycle[to]) continue; // skip other cycle edges\n            // traverse this tree branch starting at (c, to)\n            if(root[to] != -1) continue; // already visited\n            // iterative stack: node, par, depth, edge_to_parent_id\n            struct Item { int v, p, d, e; } ;\n            stack<Item> st; st.push({to, c, 1, eid});\n            while(!st.empty()){\n                auto it = st.top(); st.pop();\n                int v = it.v, p = it.p, d = it.d, e = it.e;\n                root[v] = c; depth[v] = d; parent[v] = p; edge_to_parent[v] = e;\n                for(auto [to2, eid2] : adj[v]){\n                    if(to2 == p) continue;\n                    if(inCycle[to2]) continue; // don't cross into cycle from tree\n                    if(root[to2] != -1) continue;\n                    st.push({to2, v, d+1, eid2});\n                }\n            }\n        }\n    }\n\n    // 4) maintain on/off status of edges\n    vector<char> on(n, 0);\n\n    // 5) helper: toggle path inside a single tree between a and b (may include up to LCA)\n    auto toggle_path_in_tree = [&](int a, int b){\n        // toggle edges along the path from a to b within the same tree rooted at some cycle vertex\n        while(a != b){\n            if(depth[a] > depth[b]){\n                int eid = edge_to_parent[a];\n                if(eid >= 0) on[eid] = !on[eid];\n                a = parent[a];\n            } else if(depth[b] > depth[a]){\n                int eid = edge_to_parent[b];\n                if(eid >= 0) on[eid] = !on[eid];\n                b = parent[b];\n            } else {\n                // equal depth and different; move both up\n                int eidA = edge_to_parent[a]; if(eidA >= 0) on[eidA] = !on[eidA]; a = parent[a];\n                int eidB = edge_to_parent[b]; if(eidB >= 0) on[eidB] = !on[eidB]; b = parent[b];\n            }\n        }\n    };\n\n    // 6) cycle edges: build an array of edge ids for cycle consecutive pairs\n    vector<int> cycle_edge_id(K, -1);\n    for(int i=0;i<K;++i){\n        int a = cyc[i]; int b = cyc[(i+1)%K];\n        cycle_edge_id[i] = get_edge_id(a,b);\n        // cycle_edge_id[i] must be valid\n    }\n\n    auto dist_forward = [&](int rv, int ru)->int {\n        int pa = pos[rv], pb = pos[ru];\n        int d = (pb - pa);\n        if(d < 0) d += K;\n        return d;\n    };\n    auto dist_backward = [&](int rv, int ru)->int {\n        int d = dist_forward(rv, ru);\n        return (K - d) % K;\n    };\n\n    // 7) process queries\n    auto compute_components = [&]() -> int {\n        vector<char> vis(n+1, 0);\n        int comps = 0;\n        queue<int> qq;\n        for(int i=1;i<=n;++i){ if(!vis[i]){ comps++; vis[i] = 1; qq.push(i);\n                while(!qq.empty()){\n                    int x = qq.front(); qq.pop();\n                    for(auto [y, eid] : adj[x]){\n                        if(!on[eid]) continue;\n                        if(!vis[y]){ vis[y] = 1; qq.push(y); }\n                    }\n                }\n        }}\n        return comps;\n    };\n\n    for(int qi=0; qi<m; ++qi){\n        int v,u; cin >> v >> u;\n        int rv = root[v], ru = root[u];\n        if(rv == -1) rv = v; // safety, though every vertex should have a root\n        if(ru == -1) ru = u;\n        if(rv == ru){\n            // path within same tree (or both are same cycle-root vertex)\n            toggle_path_in_tree(v, u);\n        } else {\n            // paths from v to rv and u to ru\n            if(v != rv) toggle_path_in_tree(v, rv);\n            if(u != ru) toggle_path_in_tree(u, ru);\n            // cycle arc between rv and ru\n            int ar = pos[rv]; int br = pos[ru];\n            int df = dist_forward(rv, ru); // number of edges forward\n            int db = dist_backward(rv, ru); // number of edges backward\n            bool forward_dir;\n            if(df < db) forward_dir = true;\n            else if(db < df) forward_dir = false;\n            else {\n                // tie: lexicographic tie-break using immediate next vertex from rv\n                int next_forward = cyc[(ar + 1) % K];\n                int next_backward = cyc[(ar - 1 + K) % K];\n                forward_dir = (next_forward < next_backward);\n            }\n            if(forward_dir){\n                for(int t = 0; t < df; ++t){\n                    int idx = (ar + t) % K;\n                    int eid = cycle_edge_id[idx]; if(eid >= 0) on[eid] = !on[eid];\n                }\n            } else {\n                for(int t = 0; t < db; ++t){\n                    int idx = (ar - 1 - t + K) % K;\n                    int eid = cycle_edge_id[idx]; if(eid >= 0) on[eid] = !on[eid];\n                }\n            }\n        }\n        int comps = compute_components();\n        cout << comps << \"\\n\";\n    }\n\n    return 0;\n}\nCPP\n\necho 'Wrote main.cpp'\n",
