# brute force tester for unicyclic graph solver
import random, sys, subprocess
from collections import deque

def lex_shortest_path(n, edges, v, u):
    g=[[] for _ in range(n+1)]
    for i,(a,b) in enumerate(edges): g[a].append((b,i)); g[b].append((a,i))
    for i in range(1,n+1): g[i].sort()
    dist=[-1]*(n+1); parent=[-1]*(n+1)
    dq=deque([v]); dist[v]=0
    while dq:
        x=dq.popleft()
        if x==u: break
        for to,eid in g[x]:
            if dist[to]==-1:
                dist[to]=dist[x]+1; parent[to]=x; dq.append(to)
    if dist[u]==-1: return []
    path=[]; cur=u
    while cur!=-1:
        path.append(cur)
        if cur==v: break
        cur=parent[cur]
    path.reverse()
    edge_ids=[]
    for i in range(len(path)-1):
        a,b=path[i], path[i+1]
        for nb,eid in g[a]:
            if nb==b: edge_ids.append(eid); break
    return edge_ids

def brute(n, edges, queries):
    on=[0]*len(edges)
    adj=[[] for _ in range(n+1)]
    for i,(a,b) in enumerate(edges): adj[a].append((b,i)); adj[b].append((a,i))
    for i in range(1,n+1): adj[i].sort()
    def toggle_path(v,u):
        for eid in lex_shortest_path(n, edges, v, u): on[eid]^=1
    def comps():
        vis=[False]*(n+1); c=0
        for i in range(1,n+1):
            if not vis[i]:
                c+=1; q=deque([i]); vis[i]=True
                while q:
                    x=q.popleft()
                    for y,eid in adj[x]:
                        if on[eid] and not vis[y]: vis[y]=True; q.append(y)
        return c
    res=[]
    for v,u in queries:
        toggle_path(v,u)
        res.append(comps())
    return res

random.seed(0)
for t in range(5):
    n=6
    k=random.randint(3,n-1)
    cycle=list(range(1,k+1))
    edges=[]
    for i in range(k): edges.append((cycle[i], cycle[(i+1)%k]))
    cur=k+1
    while cur<=n:
        par=random.randint(1,cur-1); edges.append((cur, par)); cur+=1
    if len(edges)!=n:
        while len(edges)<n:
            a=random.randint(1,n); b=random.randint(1,n)
            if a==b: continue
            if any((a==x and b==y) or (a==y and b==x) for x,y in edges): continue
            edges.append((a,b))
    q=random.randint(1,3)
    queries=[]
    for _ in range(q):
        v=random.randint(1,n); w=random.randint(1,n)
        while w==v: w=random.randint(1,n)
        queries.append((v,w))
    with open('tmp.in','w') as f:
        f.write(f"{n} {q}\n")
        for a,b in edges: f.write(f"{a} {b}\n")
        for v,w in queries: f.write(f"{v} {w}\n")
    import subprocess
    out=subprocess.run(['./main'], input=open('tmp.in','rb').read(), stdout=subprocess.PIPE).stdout.decode()
    prog=[int(x) for x in out.strip().split()] if out.strip() else []
    br=brute(n, edges, queries)
    if prog!=br:
        print('Mismatch!')
        print(n, edges, queries)
        print('prog', prog)
        print('brute', br)
        sys.exit(0)
print('All brute tests passed')
